/**
 * POST /api/attempts: persist evaluated attempts (doc 03 data flow step 11; doc 09 lesson_attempts).
 * Body: { attempts: [{ id, ...AttemptRecord }] } with every sessionId equal to the cookie's. `id` is generated by
 * the client, so a retried POST inserts nothing twice. MVP recomputes mastery from these rows; no progress write.
 */
import { lessonAttempts } from "@grasp/db";
import { z } from "zod";
import { badRequest, cookieSessionId, forbidden, getDb, unavailable } from "@/lib/db";

const Attempt = z.strictObject({
  id: z.uuid(),
  sessionId: z.uuid(),
  lessonId: z.string().min(1),
  lessonHash: z.string().regex(/^[0-9a-f]{64}$/),
  activityId: z.string().min(1),
  activityKind: z.enum(["guided", "challenge", "assessment"]),
  taskId: z.string().min(1),
  taskType: z.enum(["identify", "place", "remove", "sequence", "compare"]),
  objectiveId: z.string().min(1),
  attemptNo: z.int().min(0).max(100),
  microTask: z.boolean(),
  remediated: z.boolean(),
  outcome: z.enum(["correct", "partial", "incorrect"]),
  score: z.number().min(-1000).max(1000),
  scoreMax: z.number().min(0).max(1000),
  hintsUsed: z.int().min(0).max(3),
  durationMs: z.int().min(0),
  // Ids only: never positions or landmarks (doc 06 "actual").
  actual: z.strictObject({
    type: z.string(),
    componentId: z.string().optional(),
    socketId: z.string().optional(),
    hotspotId: z.string().optional(),
  }),
  t: z.int().min(0),
});
const Body = z.object({ attempts: z.array(Attempt).min(1).max(50) });

export async function POST(request: Request) {
  const parsed = Body.safeParse(await request.json().catch(() => null));
  if (!parsed.success) return badRequest(parsed.error);
  const sessionId = cookieSessionId(request);
  if (!sessionId || parsed.data.attempts.some((a) => a.sessionId !== sessionId)) return forbidden();
  const db = getDb();
  if (!db) return unavailable();
  try {
    await db
      .insert(lessonAttempts)
      .values(parsed.data.attempts.map((a) => ({ ...a, score: String(a.score), scoreMax: String(a.scoreMax) })))
      .onConflictDoNothing();
    return new Response(null, { status: 204 });
  } catch (err) {
    console.error("POST /api/attempts", err);
    return unavailable();
  }
}
